#include <iostream>
#include <thread>
#include <mutex>
using namespace std;

int counter = 0;
mutex m;

void work() {
    lock_guard<mutex> guard(m);
    ++counter;
}

int main() {
    thread t1(work), t2(work);
    t1.join(); t2.join();
    cout << counter << '\n';
}

